from taf.rfrl.l3_call.cell.classical_cell.classical_cell import ClassicalCell
from taf.rfrl.l3_call.cell.exceptions import CellIdNotFound
from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output, log_result, log_to_console


class ClassicalWcdmaCell(ClassicalCell):
    def __init__(self, cell_distname, bts_connection_alias, shared_spectrum):
        super(ClassicalWcdmaCell, self).__init__(cell_distname, bts_connection_alias, shared_spectrum)
        self._type = "wcdma"

    def __str__(self):
        return "ClassicalWcdmaCell cell instance for {0} for cell type".format(self._type)

    def get_spectrum(self, cells_info, cell_specific_info):
        log_result("No need to calculate spectrum for WCDMA cell, returning zero")
        return [0, 0]

    def _is_beamforming_activated(self):
        return False

    @log_input_and_output
    def _get_cell_id(self):
        cells_info = self._api.get_cells_info(connection=self._connection, cell_type="wcdma")
        for cell in cells_info:
            if cell["id"]["configuration"] == self.distname:
                return cell["wncelId"]

        raise CellIdNotFound("Cell ID not found for cell {}".format(self.distname))

    def _get_cell_technology(self):
        log_result("Cell technology is not available for WCDMA cell")
        return None

    def _get_narrowband_iot_mode(self):
        log_result("IoT mode is not available for WCDMA cell")
        return None

    def _make_callable(self, delta):
        if not self._check_blocking_state(expected_state="Unblocked"):
            log_to_console("Making cell {} callable".format(self.distname))
            self._unblock_cell()
            self._check_blocking_state(expected_state="Unblocked")

    def _make_uncallable(self, delta):
        if not self._check_blocking_state(expected_state="Blocked"):
            log_to_console("Blocking cell {}".format(self.distname))
            self._block_cell()
            self._check_blocking_state(expected_state="Blocked")
